// Parses the incoming Database Webhook call and validates that it is
// really a new-row INSERT on the `posts` table before doing any work.
//
// Works out of the box with Supabase "Database Webhooks", whose payload
// shape is: { type, table, schema, record, old_record }.
// If you're firing this from a Postgres trigger + pg_notify bridge or a
// custom backend hook instead, just adjust the field paths below to match
// whatever your bridge sends - the rest of the workflow doesn't care.

const body = $('Post Created (Webhook)').first().json.body;

const isInsert   = body.type === 'INSERT';
const isPostsRow = body.table === 'posts';
const record     = body.record || {};

const content   = (record.content || record.text || record.caption || record.body || '').toString();
const mediaUrl  = record.media_url || record.video_url || null;
const mediaType = record.media_type || (mediaUrl ? 'media' : 'text');

return [{
  json: {
    isValidEvent: Boolean(isInsert && isPostsRow && record.id),
    postId:     record.id ?? null,
    authorId:   record.author_id ?? record.user_id ?? null,
    content,
    mediaUrl,
    mediaType,
    createdAt:  record.created_at ?? new Date().toISOString()
  }
}];

// --- Keyword moderation pass ------------------------------------------
// Fast, free, zero-latency first line of defence. Runs on every post
// before the (paid, slower) AI check is even considered.
//
// IMPORTANT: The `hateSpeech` list is intentionally left empty in this
// template. Hard-coding slurs into a shared repo is bad practice - most
// teams instead (a) load a vetted list from a private config table /
// environment variable at runtime, or (b) lean on the AI moderation step
// below, or (c) call a dedicated classifier like Google's Perspective
// API (see README "Extending the hate-speech check"). Populate
// `hateSpeech` with your own reviewed list before the demo if you want a
// keyword-only fallback for this category.

const config = $('⚙️ Configuration').first().json;

const KEYWORDS = {
  harassment: [
    'kill yourself', 'kys', 'you should die', 'i hope you die',
    'worthless piece of', 'nobody likes you', 'end your life', 'ffs', 'Ffs'
  ],
  spam: [
    'click here to win', 'guaranteed income', 'work from home $$$',
    'free followers', 'act now', 'limited time offer', 'dm to buy followers'
  ],
  scam: [
    'send bitcoin', 'wire transfer now', 'urgent payment required',
    'send gift cards', 'crypto investment opportunity', 'claim your prize'
  ],
  profanity: [
    'fuck', 'shit', 'bitch', 'asshole', 'bastard', 'ass', 'cunt', 'nigga', 'nigger', 'gay', 'fag', 'fagget'
  ],
  hateSpeech: [
    // populate with your institution's vetted list - see note above
  ]
};

const SEVERITY = { harassment: 4, scam: 4, hateSpeech: 5, spam: 2, profanity: 1 };

const text = (($json.content || '') + '').toLowerCase();

let score = 0;
const matches = [];

for (const [category, terms] of Object.entries(KEYWORDS)) {
  for (const term of terms) {
    if (term && text.includes(term.toLowerCase())) {
      score += SEVERITY[category] || 1;
      matches.push({ category, term });
    }
  }
}

return [{
  json: {
    ...$json,
    keywordScore: score,
    keywordMatches: matches,
    keywordFlagged: score >= config.keywordThreshold
  }
}];

// Builds the Gemini request body. Kept as its own node so the HTTP
// Request node stays a simple, readable "just send this" call.

const post = $json;

const prompt = `You are a content-moderation classifier for a professional
student/alumni networking platform (similar in tone to LinkedIn).
Classify the following user post. Respond with ONLY a JSON object
(no markdown, no commentary) matching exactly this shape:
{"flagged": boolean, "category": "harassment|hate_speech|spam|scam|nudity|violence|none", "severity": 1-5, "reason": "short human-readable reason"}

Flag content that is harassing, hateful, sexually explicit, violent,
a scam/phishing attempt, or clearly spam. Do NOT flag ordinary strong
opinions, negative reviews, competitive banter, or normal profanity used
casually - this platform is used by adults and over-flagging erodes trust.

=== POST CONTENT START ===
${(post.content || '').slice(0, 4000)}
=== POST CONTENT END ===`;

return [{
  json: {
    ...post,
    geminiRequestBody: {
      contents: [{ parts: [{ text: prompt }] }],
      generationConfig: {
        temperature: 0,
        responseMimeType: 'application/json'
      }
    }
  }
}];

// Parses Gemini's response. If anything about the AI call goes wrong
// (bad JSON, safety block, network hiccup) we fail OPEN on the AI layer
// - i.e. we do NOT flag the post just because the AI call broke, since
// the keyword pass has already run and this is only the extra layer.
// The error is still surfaced in `aiError` so you can alert on it.

let aiFlagged = false;
let aiCategory = 'none';
let aiSeverity = 0;
let aiReason = '';
let aiError = null;

try {
  const candidates = $json.candidates || [];
  const rawText = candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  const cleaned = rawText.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(cleaned);

  aiFlagged  = Boolean(parsed.flagged);
  aiCategory = parsed.category || 'none';
  aiSeverity = Number(parsed.severity) || 0;
  aiReason   = parsed.reason || '';
} catch (err) {
  aiError = err.message;
}

const post = $('Keyword Scan').first().json;

return [{
  json: {
    ...post,
    aiFlagged,
    aiCategory,
    aiSeverity,
    aiReason,
    aiError
  }
}];

// Builds the content_reports insert payload when the KEYWORD pass is
// what triggered the flag (AI step is skipped entirely in this branch).
//
// content_id/content_type match the live content_reports schema (verified
// 2026-09-16) - the table has no post_id column, and content_type is
// NOT NULL with a CHECK allowing only 'post'/'comment'/'video'.

const p = $json;
const topMatch = (p.keywordMatches || [])[0] || {};

return [{
  json: {
    content_id: p.postId,
    content_type: 'post',
    reported_by: null, // NULL = system-generated report, exactly what the
                        // Flagged Content queue is designed to accept
    report_type: 'automated',
    reason: `Keyword filter: matched "${topMatch.term}" (${topMatch.category}). ` +
            `${p.keywordMatches.length} total match(es), score ${p.keywordScore}.`,
    category: topMatch.category || 'other',
    severity: p.keywordScore,
    status: 'pending',
    flagged_by: 'system:keyword-filter',
    created_at: new Date().toISOString()
  }
}];

// Builds the content_reports insert payload when the AI (Gemini) pass
// is what triggered the flag - i.e. the keyword pass found nothing, but
// Gemini judged the content should be reviewed.
//
// content_id/content_type match the live content_reports schema (verified
// 2026-09-16) - the table has no post_id column, and content_type is
// NOT NULL with a CHECK allowing only 'post'/'comment'/'video'.

const p = $json;

return [{
  json: {
    content_id: p.postId,
    content_type: 'post',
    reported_by: null, // system-generated report
    report_type: 'automated',
    reason: `AI moderation: ${p.aiReason || 'flagged by Gemini content check'}`,
    category: p.aiCategory || 'other',
    severity: p.aiSeverity || 3,
    status: 'pending',
    flagged_by: 'system:gemini-moderation',
    created_at: new Date().toISOString()
  }
}];
